// Generated by esquadro: do not edit. Reading a CSV file for an import: its
// rows, which field each column fills, and its values as the API takes
// them, read in the frontend's language as the export writes them
// ("1.234,56" and "18 de nov. de 2026" in pt-BR).
import { cell } from "./export.ts"
import type { FieldMeta } from "./meta.ts"

/** A CSV file: its separator, the header's names and the rows under it. */
export interface Csv {
  separator: string
  header: string[]
  rows: string[][]
}

/**
 * Reads CSV text: the separator the first line uses most (";", "," or a
 * tab), quoted cells with "" for a quote and line breaks inside, a
 * byte-order mark, and blank lines left out.
 */
export function parseCsv(text: string): Csv {
  const src = text.replace(/^﻿/, "")
  const separator = guessSeparator(src)
  const lines: string[][] = []
  let row: string[] = []
  let value = ""
  let quoted = false
  for (let i = 0; i < src.length; i++) {
    const c = src[i]
    if (quoted) {
      if (c === '"' && src[i + 1] === '"') {
        value += '"'
        i++
      } else if (c === '"') {
        quoted = false
      } else {
        value += c
      }
      continue
    }
    if (c === '"' && value === "") {
      quoted = true
    } else if (c === separator) {
      row.push(value)
      value = ""
    } else if (c === "\n" || c === "\r") {
      if (c === "\r" && src[i + 1] === "\n") i++
      row.push(value)
      lines.push(row)
      row = []
      value = ""
    } else {
      value += c
    }
  }
  if (value !== "" || row.length > 0) {
    row.push(value)
    lines.push(row)
  }
  const full = lines.filter((l) => l.some((v) => v.trim() !== ""))
  const [header = [], ...rows] = full
  return { separator, header: header.map((h) => h.trim()), rows }
}

function guessSeparator(src: string): string {
  const first = src.slice(0, src.search(/\r?\n|$/))
  let best = ","
  let most = 0
  for (const sep of [";", ",", "\t"]) {
    let n = 0
    let quoted = false
    for (const c of first) {
      if (c === '"') quoted = !quoted
      else if (c === sep && !quoted) n++
    }
    if (n > most) {
      best = sep
      most = n
    }
  }
  return best
}

/** A name as compared: lowercase, without accents and punctuation. */
export function normalize(s: string): string {
  return s
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
}

/** Where a column goes: a field, or a money field's currency. */
export type Target = string | null

/** The name of a money field's currency column, as a target. */
export const currencyOf = (field: string) => `${field}#currency`

/**
 * The field each column fills, guessed from its name: the field's label or
 * name, in any case and without accents; "<label> (<currency>)", as the
 * export writes it, for a money field's currency. A field is given to one
 * column at most; remembered, when given, wins.
 */
export function suggest(header: string[], fields: FieldMeta[], currencyWord: string, remembered: Record<string, string> = {}): Target[] {
  const taken = new Set<string>()
  const names = new Map<string, string>()
  for (const f of fields) {
    names.set(normalize(f.label), f.name)
    names.set(normalize(f.name), f.name)
    if (f.kind === "relation") names.set(normalize(f.name.replace(/_id$/, "")), f.name)
    if (f.kind === "money") {
      names.set(normalize(`${f.label} (${currencyWord})`), currencyOf(f.name))
      names.set(normalize(`${f.name}_currency`), currencyOf(f.name))
    }
  }
  const known = new Set([...names.values()])
  return header.map((h) => {
    const key = normalize(h)
    const remember = remembered[key]
    const target = remember !== undefined && (remember === "" || known.has(remember)) ? remember || null : (names.get(key) ?? null)
    if (target === null || taken.has(target)) return null
    taken.add(target)
    return target
  })
}

/** A value as the API takes it, or why it could not be read. */
export interface Read {
  value?: unknown
  error?: string
}

const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

/** The separator of decimals in a language: "," in pt-BR, "." in en. */
export function decimalOf(locale: string): string {
  return (1.5).toLocaleString(locale).replace(/\d/g, "") || "."
}

/**
 * A number as text, with a point for decimals ("1234.56"), from one written
 * in the language or not: "1.234,56", "1,234.56", "R$ 1.234,56", "1234.56".
 * Null when it is none.
 */
export function parseNumber(text: string, locale: string): string | null {
  let s = text.replace(/[^\d.,+-]/g, "")
  if (!/\d/.test(s)) return null
  const dot = s.includes(".")
  const comma = s.includes(",")
  let decimal = ""
  if (dot && comma) {
    decimal = s.lastIndexOf(".") > s.lastIndexOf(",") ? "." : ","
  } else if (dot || comma) {
    const c = dot ? "." : ","
    const grouped = new RegExp(`^[+-]?\\d{1,3}(\\${c}\\d{3})+$`)
    // One mark: the language's decimals, or a thousands' when it groups
    // threes ("1.500" in pt-BR); else decimals anyway ("1.5").
    decimal = c === decimalOf(locale) || !grouped.test(s) ? c : ""
  }
  const group = decimal === "." ? "," : decimal === "," ? "." : dot ? "." : ","
  s = s.split(group).join("")
  if (decimal) s = s.replace(decimal, ".")
  return /^[+-]?\d+(\.\d+)?$/.test(s) ? s.replace(/^\+/, "") : null
}

/** The months' names in a language, normalized: long, then short. */
function monthsOf(locale: string): string[][] {
  return Array.from({ length: 12 }, (_, m) => {
    const at = new Date(Date.UTC(2020, m, 15))
    return ["long", "short"].map((month) =>
      normalize(new Intl.DateTimeFormat(locale, { month: month as "long" | "short", timeZone: "UTC" }).format(at)),
    )
  })
}

const pad = (n: number, size = 2) => String(n).padStart(size, "0")

function validDay(y: number, m: number, d: number): boolean {
  const at = new Date(Date.UTC(y, m - 1, d))
  return at.getUTCFullYear() === y && at.getUTCMonth() === m - 1 && at.getUTCDate() === d
}

/**
 * A date as YYYY-MM-DD, from 2026-11-18, 18/11/2026 (11/18/2026 in en),
 * or as the language writes it with the month's name ("18 de nov. de
 * 2026", "Nov 18, 2026"). Null when it is none.
 */
export function parseDate(text: string, locale: string): string | null {
  const iso = text.trim().match(/^(\d{4})-(\d{1,2})-(\d{1,2})/)
  let y: number, m: number, d: number
  if (iso) {
    ;[y, m, d] = [Number(iso[1]), Number(iso[2]), Number(iso[3])]
  } else {
    const tokens = normalize(text).split(" ").filter(Boolean)
    const numbers = tokens.filter((t) => /^\d+$/.test(t)).map(Number)
    const words = tokens.filter((t) => !/^\d+$/.test(t) && t.length >= 3)
    const months = monthsOf(locale)
    const named = words.map((w) => months.findIndex((names) => names.some((n) => n === w || (n.length >= 3 && (n.startsWith(w) || w.startsWith(n)))))).find((i) => i >= 0)
    if (named !== undefined) {
      const year = numbers.find((n) => n > 31)
      const day = numbers.find((n) => n !== year)
      if (year === undefined || day === undefined) return null
      ;[y, m, d] = [year, named + 1, day]
    } else if (numbers.length >= 3) {
      const [a, b, c] = numbers
      if (a > 31) [y, m, d] = [a, b, c]
      else if (locale.startsWith("en")) [y, m, d] = [c, a, b]
      else [y, m, d] = [c, b, a]
    } else {
      return null
    }
    if (y < 100) y += 2000
  }
  return validDay(y, m, d) ? `${pad(y, 4)}-${pad(m)}-${pad(d)}` : null
}

/**
 * A moment as an ISO instant: an ISO one as it is, or a date as parseDate
 * reads it with a time (14:30, 2:30 PM), in the browser's time zone. Null
 * when it is none.
 */
export function parseDateTime(text: string, locale: string): string | null {
  const s = text.trim()
  if (/^\d{4}-\d{2}-\d{2}T/.test(s)) {
    const at = new Date(s)
    return Number.isNaN(at.getTime()) ? null : at.toISOString()
  }
  const time = s.match(/(\d{1,2}):(\d{2})(?::(\d{2}))?\s*([ap]\.?\s?m\.?)?/i)
  const day = parseDate(time ? s.replace(time[0], " ") : s, locale)
  if (!day) return null
  let h = time ? Number(time[1]) : 0
  const pm = time?.[4]?.toLowerCase().startsWith("p")
  if (time?.[4] && h === 12) h = 0
  if (pm) h += 12
  const [y, m, d] = day.split("-").map(Number)
  const at = new Date(y, m - 1, d, h, time ? Number(time[2]) : 0, time?.[3] ? Number(time[3]) : 0)
  return Number.isNaN(at.getTime()) ? null : at.toISOString()
}

/** The words a yes or a no is written with, besides the language's. */
const yes = ["true", "1", "yes", "y", "sim", "s", "si", "x", "verdadeiro", "v"]
const no = ["false", "0", "no", "n", "nao", "falso", "f"]

/**
 * A cell as the API takes the field's value: undefined when it is empty;
 * the error's code (invalid_value) when it cannot be read. Relations,
 * money and lists are read apart (readRows).
 */
export function readValue(field: FieldMeta, text: string, locale: string, words: { yes: string; no: string }): Read {
  const s = text.trim()
  if (s === "") return {}
  const invalid = { error: "invalid_value" }
  switch (field.kind) {
    case "int": {
      const n = parseNumber(s, locale)
      return n !== null && /^-?\d+$/.test(n) ? { value: Number(n) } : invalid
    }
    case "decimal": {
      const n = parseNumber(s, locale)
      return n !== null ? { value: n } : invalid
    }
    case "bool": {
      const v = normalize(s)
      if (v === normalize(words.yes) || yes.includes(v)) return { value: true }
      if (v === normalize(words.no) || no.includes(v)) return { value: false }
      return invalid
    }
    case "date": {
      const d = parseDate(s, locale)
      return d ? { value: d } : invalid
    }
    case "datetime": {
      const d = parseDateTime(s, locale)
      return d ? { value: d } : invalid
    }
    case "enum": {
      const v = normalize(s)
      const found = (field.values ?? []).find((x) => normalize(x) === v || normalize(field.labels?.[x] ?? "") === v)
      return found !== undefined ? { value: found } : invalid
    }
    case "uuid":
      return uuid.test(s) ? { value: s.toLowerCase() } : invalid
    case "json":
      try {
        return { value: JSON.parse(s) }
      } catch {
        return invalid
      }
  }
  return { value: field.kind === "text" ? s : text }
}

/** A row refused: its number in the file (from 1, the header left out), the field and why. */
export interface RowProblem {
  row: number
  field: string
  code: string
}

/** The records of another resource by the text that shows them, for its relations. */
export type Lookup = Map<string, string[]>

/** The fields an import may fill: what a create takes, but files and lists. */
export function importable(fields: FieldMeta[]): FieldMeta[] {
  return fields.filter((f) => !f.readOnly && f.kind !== "file" && f.kind !== "image" && f.kind !== "many")
}

/**
 * The file's rows as records the API takes, with what is wrong with each:
 * a required field empty (unless it has a default, which it takes), a
 * value that cannot be read, a relation by a text no record shows
 * (not_found) or more than one does (ambiguous), or by its id.
 */
export function readRows(
  csv: Csv,
  targets: Target[],
  fields: FieldMeta[],
  options: { locale: string; currency: string; words: { yes: string; no: string }; lookups: Record<string, Lookup> },
): { records: Record<string, unknown>[]; problems: RowProblem[] } {
  const byName = new Map(fields.map((f) => [f.name, f]))
  const records: Record<string, unknown>[] = []
  const problems: RowProblem[] = []
  csv.rows.forEach((cells, i) => {
    const row = i + 1
    const record: Record<string, unknown> = {}
    const currencies: Record<string, string> = {}
    targets.forEach((target, col) => {
      if (target === null) return
      const text = cells[col] ?? ""
      if (target.endsWith("#currency")) {
        if (text.trim()) currencies[target.slice(0, -"#currency".length)] = text.trim().toUpperCase()
        return
      }
      const field = byName.get(target)
      if (!field) return
      if (field.kind === "relation") {
        const s = text.trim()
        if (!s) return
        if (uuid.test(s)) {
          record[field.name] = s.toLowerCase()
          return
        }
        const ids = options.lookups[field.name]?.get(normalize(s)) ?? []
        if (ids.length === 1) record[field.name] = ids[0]
        else problems.push({ row, field: field.name, code: ids.length === 0 ? "not_found" : "ambiguous" })
        return
      }
      if (field.kind === "money") {
        const n = text.trim() ? parseNumber(text, options.locale) : undefined
        if (n === null) problems.push({ row, field: field.name, code: "invalid_value" })
        else if (n !== undefined) record[field.name] = { amount: n, currency: "" }
        return
      }
      const read = readValue(field, text, options.locale, options.words)
      if (read.error) problems.push({ row, field: field.name, code: read.error })
      else if (read.value !== undefined) record[field.name] = read.value
    })
    for (const f of fields) {
      const v = record[f.name]
      if (f.kind === "money" && v && typeof v === "object") {
        const fallback = typeof f.default === "object" && f.default && "currency" in f.default ? String((f.default as { currency?: string }).currency ?? "") : ""
        ;(v as { currency: string }).currency = currencies[f.name] || fallback || options.currency
      }
      if (v !== undefined || problems.some((p) => p.row === row && p.field === f.name)) continue
      if (f.default !== undefined) record[f.name] = f.default
      else if (f.required && f.kind !== "bool") problems.push({ row, field: f.name, code: "required" })
    }
    records.push(record)
  })
  return { records, problems }
}

/**
 * The rows with problems as a CSV, to fix and import again: the file's
 * columns, and a last one saying what is wrong in each.
 */
export function problemsCsv(csv: Csv, problems: RowProblem[], describe: (p: RowProblem) => string, column: string): string {
  const byRow = new Map<number, RowProblem[]>()
  for (const p of problems) byRow.set(p.row, [...(byRow.get(p.row) ?? []), p])
  const sep = csv.separator
  const lines = [[...csv.header, column].map((h) => cell(h, sep)).join(sep)]
  for (const [row, list] of [...byRow].sort((a, b) => a[0] - b[0])) {
    const cells = csv.rows[row - 1] ?? []
    const padded = csv.header.map((_, i) => cells[i] ?? "")
    lines.push([...padded, list.map(describe).join("; ")].map((v) => cell(v, sep)).join(sep))
  }
  return lines.join("\r\n") + "\r\n"
}
